export const calendarFires = pgTable("calendar_fires", {
	routineId: uuid("routine_id").notNull(),
	eventId: text("event_id").notNull(),
	orgId: uuid("org_id").notNull(),
	fireAt: timestamp("fire_at", { withTimezone: true, mode: 'string' }).notNull(),
	event: jsonb().notNull(),
	firedAt: timestamp("fired_at", { withTimezone: true, mode: 'string' }),
	runId: uuid("run_id"),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	index("calendar_fires_due_idx").using("btree", table.fireAt.asc().nullsLast().op("timestamptz_ops")).where(sql`(fired_at IS NULL)`),
	foreignKey({
			columns: [table.routineId],
			foreignColumns: [routines.id],
			name: "calendar_fires_routine_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.orgId],
			foreignColumns: [organizations.id],
			name: "calendar_fires_org_id_fkey"
		}).onDelete("cascade"),
	primaryKey({ columns: [table.routineId, table.eventId], name: "calendar_fires_pkey"}),
	pgPolicy("kasama_worker_all", { as: "permissive", for: "all", to: ["kasama_worker"], using: sql`true`, withCheck: sql`true`  }),
	check("calendar_fires_event_id_check", sql`(char_length(event_id) >= 1) AND (char_length(event_id) <= 500)`),
]);

export const teachSteps = pgTable("teach_steps", {
	sessionId: uuid("session_id").notNull(),
	seq: integer().notNull(),
	orgId: uuid("org_id").notNull(),
	kind: text().notNull(),
	x: integer(),
	y: integer(),
	button: smallint(),
	text: text(),
	key: text(),
	dx: integer(),
	dy: integer(),
	secretName: text("secret_name"),
	password: boolean().default(false).notNull(),
	url: text(),
	snapshot: text(),
	// TODO: failed to parse database type 'bytea'
	screenshot: text("screenshot"),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	foreignKey({
			columns: [table.sessionId],
			foreignColumns: [teachSessions.id],
			name: "teach_steps_session_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.orgId],
			foreignColumns: [organizations.id],
			name: "teach_steps_org_id_fkey"
		}).onDelete("cascade"),
	primaryKey({ columns: [table.sessionId, table.seq], name: "teach_steps_pkey"}),
	pgPolicy("teach_steps_select", { as: "permissive", for: "select", to: ["authenticated"], using: sql`(EXISTS ( SELECT 1
   FROM teach_sessions s
  WHERE ((s.id = teach_steps.session_id) AND (s.user_id = ( SELECT auth.uid() AS uid)))))` }),
	pgPolicy("kasama_worker_all", { as: "permissive", for: "all", to: ["kasama_worker"] }),
	check("teach_steps_kind_check", sql`kind = ANY (ARRAY['click'::text, 'type'::text, 'key'::text, 'scroll'::text])`),
	check("teach_steps_text_check", sql`char_length(text) <= 2000`),
	check("teach_steps_key_check", sql`char_length(key) <= 40`),
	check("teach_steps_secret_name_check", sql`secret_name ~ '^[A-Z][A-Z0-9_]{0,63}$'::text`),
	check("teach_steps_url_check", sql`char_length(url) <= 2000`),
	check("teach_steps_snapshot_check", sql`char_length(snapshot) <= 20000`),
	check("teach_steps_screenshot_check", sql`octet_length(screenshot) <= 3000000`),
]);
